/**
 * Shared focusability queries for the overlay behavior layer.
 *
 * One home for the selector the modal components previously each carried a
 * copy of. Plain DOM utilities — no React, safe to import anywhere.
 */

/** Everything a focus trap must cycle through. */
export const FOCUSABLE =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * The subset worth landing initial focus on: real controls, not arbitrary
 * tabindex carriers (a scrollable body region is tabbable but focusing it on
 * open would strand a keyboard user on a non-control).
 */
export const INITIAL_FOCUS =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled])';

/**
 * `checkVisibility` is Baseline but this must not throw in older test
 * environments; `offsetParent` is the fallback (null for `display: none`
 * subtrees, which is the case that matters for the trap).
 */
const isVisible = (el: HTMLElement): boolean =>
  typeof el.checkVisibility === 'function' ? el.checkVisibility() : el.offsetParent !== null;

/**
 * The focusable elements inside a container, in DOM order, excluding
 * invisible ones — a control hidden by `display: none` must not count as the
 * trap's first or last stop.
 */
export function getFocusable(container: HTMLElement): HTMLElement[] {
  return Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(isVisible);
}

/**
 * Where initial focus should land when a scope activates: the first visible
 * real control, then the first visible focusable of any kind, else null (the
 * caller falls back to the container itself).
 */
export function getInitialFocus(container: HTMLElement): HTMLElement | null {
  const preferred = Array.from(container.querySelectorAll<HTMLElement>(INITIAL_FOCUS)).find(
    isVisible,
  );
  return preferred ?? getFocusable(container)[0] ?? null;
}

'use client';

import { useEffect, useRef } from 'react';
import { getFocusable, getInitialFocus } from './focusable';

/**
 * Focus containment for modal overlays: initial focus, Tab wrapping, focus
 * restore, and background isolation.
 *
 * Restore is guarded by `document.contains` — the element that opened a
 * dialog can be gone by the time it closes (a row the dialog itself deleted),
 * and restoring into a detached node silently drops focus to `<body>`. It
 * also runs when the component unmounts while open, which the per-component
 * implementations this replaces never handled.
 *
 * Background isolation uses `inert`, not `aria-hidden`: a JS focus trap only
 * fences the Tab key, while a screen reader's virtual cursor walks the page
 * behind the dialog freely. `inert` closes all three doors at once —
 * assistive-tech traversal, focusability, and pointer events. Scopes stack:
 * only the topmost active scope's overlay is interactive, and closing it
 * hands the page back to the scope below, not to the whole document. The
 * inert set is recomputed only when a scope activates or deactivates, so a
 * portal that mounts *while* a modal is open (a toast, say) is not inerted
 * until the stack next changes — under `aria-modal` that content is outside
 * the dialog's world anyway.
 */

type FocusScopeOptions = {
  /** Whether the scope is active — the overlay's open state. */
  active: boolean;
  /** Wrap Tab / Shift+Tab within the scope. Default true. */
  trap?: boolean;
  /** Restore focus to the previously focused element on deactivate. Default true. */
  restoreFocus?: boolean;
  /**
   * Where initial focus lands. Defaults to the first visible real control,
   * then the first focusable of any kind, then the container itself.
   */
  initialFocus?: () => HTMLElement | null;
  /** Make everything outside the scope inert while active. Default true. */
  inertOutside?: boolean;
};

type InertScope = { panel: HTMLElement };

const inertScopes: InertScope[] = [];
/** Elements this module made inert — never touches a consumer's own `inert`. */
const inerted = new Set<HTMLElement>();

const applyInert = () => {
  const top = inertScopes[inertScopes.length - 1];
  for (const child of Array.from(document.body.children)) {
    if (!(child instanceof HTMLElement)) continue;
    if (child.tagName === 'SCRIPT' || child.tagName === 'STYLE') continue;
    const shouldBeInert = top !== undefined && !child.contains(top.panel);
    if (shouldBeInert && !child.inert) {
      child.inert = true;
      inerted.add(child);
    } else if (!shouldBeInert && inerted.has(child)) {
      child.inert = false;
      inerted.delete(child);
    }
  }
  // Anything left inert but detached from the body (a removed portal) has no
  // effect; drop the bookkeeping once the stack empties.
  if (top === undefined && inerted.size > 0) {
    for (const el of inerted) el.inert = false;
    inerted.clear();
  }
};

export function useFocusScope(
  ref: React.RefObject<HTMLElement | null>,
  options: FocusScopeOptions,
): void {
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  const { active } = options;
  useEffect(() => {
    if (!active) return;
    const panel = ref.current;
    if (!panel) return;

    const previousFocus = document.activeElement as HTMLElement | null;

    // At effect time the panel can still be computed `visibility: hidden` —
    // the open transition has not started — and focusing a hidden element is
    // a silent no-op. Retry across a few frames until the focus takes; the
    // element is re-resolved per attempt because visibility gates what the
    // focusable query can see.
    let focusRaf = 0;
    let focusAttempts = 0;
    const tryInitialFocus = () => {
      const initial = optionsRef.current.initialFocus?.() ?? getInitialFocus(panel) ?? panel;
      initial.focus();
      if (document.activeElement === initial) return;
      focusAttempts += 1;
      if (focusAttempts < 5) focusRaf = requestAnimationFrame(tryInitialFocus);
    };
    tryInitialFocus();

    const scope: InertScope = { panel };
    if (optionsRef.current.inertOutside !== false) {
      inertScopes.push(scope);
      applyInert();
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab' || optionsRef.current.trap === false) return;
      const focusable = getFocusable(panel);
      if (focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      cancelAnimationFrame(focusRaf);
      document.removeEventListener('keydown', handleKeyDown);
      const index = inertScopes.indexOf(scope);
      if (index !== -1) {
        inertScopes.splice(index, 1);
        applyInert();
      }
      if (
        optionsRef.current.restoreFocus !== false &&
        previousFocus &&
        document.contains(previousFocus)
      ) {
        previousFocus.focus();
      }
    };
  }, [active, ref]);
}

'use client';

import { useEffect, useRef } from 'react';

/**
 * The dismissal layer stack — the single owner of the document-level Escape
 * and outside-press listeners for every overlay in the library.
 *
 * Before this existed, each open overlay registered its own document keydown,
 * so Escape over a stacked Dialog-in-Drawer closed both at once. The stack
 * routes each interaction to the **topmost** open layer only: Escape
 * dismisses it (or is swallowed when it is not Escape-dismissible — a lower
 * layer must never close through a blocking one), and an outside press
 * dismisses it only when the press lands outside every element the layer
 * claims. Layers below are untouched; one press, one layer.
 *
 * Exactly two document listeners exist while any layer is open, and none
 * while the stack is empty. Registration order is stack order — overlays
 * portal into `document.body` in the order they open, so stack order and
 * paint order agree without reading z-index.
 */

type LayerOptions = {
  /** The overlay's open state — the layer registers while true. */
  open: boolean;
  /** Called when the stack decides this layer should dismiss. */
  onDismiss?: () => void;
  /** Whether Escape dismisses this layer. Default true. */
  dismissOnEscape?: boolean;
  /**
   * Whether a pointerdown outside `getElements()` dismisses this layer.
   * Default false — modal components keep their own backdrop click handler,
   * which is part of their DOM and needs no document listener.
   */
  dismissOnOutsidePress?: boolean;
  /**
   * The elements that count as "inside" for outside-press checks — typically
   * the panel and its trigger. Only read when `dismissOnOutsidePress` is on.
   */
  getElements?: () => (HTMLElement | null | undefined)[];
};

type Layer = { optionsRef: React.RefObject<LayerOptions> };

const layers: Layer[] = [];
let listenersInstalled = false;

const handleKeyDown = (event: KeyboardEvent) => {
  if (event.key !== 'Escape') return;
  const top = layers[layers.length - 1];
  if (!top) return;
  const options = top.optionsRef.current;
  // A non-dismissible topmost layer swallows Escape by doing nothing: the
  // layers beneath it must not receive it either.
  if (options.dismissOnEscape === false) return;
  event.preventDefault();
  options.onDismiss?.();
};

const handlePointerDown = (event: PointerEvent) => {
  const top = layers[layers.length - 1];
  if (!top) return;
  const options = top.optionsRef.current;
  if (!options.dismissOnOutsidePress) return;
  const target = event.target instanceof Node ? event.target : null;
  if (!target) return;
  const inside = (options.getElements?.() ?? []).some((el) => el?.contains(target));
  if (!inside) options.onDismiss?.();
};

const syncListeners = () => {
  if (layers.length > 0 && !listenersInstalled) {
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('pointerdown', handlePointerDown);
    listenersInstalled = true;
  } else if (layers.length === 0 && listenersInstalled) {
    document.removeEventListener('keydown', handleKeyDown);
    document.removeEventListener('pointerdown', handlePointerDown);
    listenersInstalled = false;
  }
};

/**
 * Register an overlay on the dismissal stack while `open` is true. Options
 * are read at event time, so a `dismissOnEscape` toggle takes effect without
 * re-registering (which would wrongly move the layer to the top).
 */
export function useLayer(options: LayerOptions): void {
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  const { open } = options;
  useEffect(() => {
    if (!open) return;
    const layer: Layer = { optionsRef };
    layers.push(layer);
    syncListeners();
    return () => {
      const index = layers.indexOf(layer);
      if (index !== -1) layers.splice(index, 1);
      syncListeners();
    };
  }, [open]);
}

'use client';

import { useSyncExternalStore } from 'react';

const emptySubscribe = () => () => {};

/**
 * False during SSR and the hydration render, true afterwards — the guard a
 * portal component needs before touching `document.body`. Uses
 * `useSyncExternalStore` rather than a mount effect so the client's first
 * render matches the server HTML without an extra render pass.
 */
export function useMounted(): boolean {
  return useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false,
  );
}

'use client';

import { useEffect, useRef } from 'react';

/**
 * Page scroll locking for modal overlays, with two strategies and one owner.
 *
 * `pin` (the default) fixes the body in place rather than hiding its
 * overflow. iOS Safari ignores `overflow: hidden` on the body: a touch still
 * scrolls the document, and focusing a field scrolls it programmatically to
 * bring the field above the keyboard — which slides the page out from under
 * the overlay. A fixed body has no scrollable overflow at all, so neither can
 * move it. The body is pinned at its current scroll offset so the page behind
 * the overlay does not visibly jump, and the offset is restored when the last
 * holder releases. `overflow: hidden` rides along so the pinned body cannot
 * grow scrollbars of its own.
 *
 * The pin is **counted**, and the counter is the whole point: closing a
 * Dialog opened over a Drawer must not unlock the Drawer's scroll. The
 * imperative pair (`acquireScrollLock` / `releaseScrollLock`) exposes the
 * same counter to host chrome — a site's nav drawer, a bespoke chat panel —
 * because two locks that cannot see each other each believe they own
 * `document.body`, and whichever releases first unlocks the page under the
 * overlay the other still holds (or restores styles the other already
 * changed). One counter means the first acquire captures and pins, only the
 * last release restores, whichever module it belongs to. The captured inline
 * styles are restored verbatim, never blanked, so a host's own body styling
 * survives a lock cycle.
 *
 * `cancel-events` keeps the document scrollbar rendered and cancels scroll
 * *input* instead — wheel and touch gestures work only inside `allowWithin`.
 * This is CommandPalette's documented design decision (unscrollable-body
 * treatments blink the scrollbar rail out, which reads as a layout jump on
 * classic-scrollbar platforms); it is deliberately not the default because
 * swapping the modals onto it would change their scrollbar rendering.
 * Instances are independent — overlapping cancel-events locks stack
 * harmlessly.
 */

type ScrollLockOptions = {
  /** Which locking strategy to use. Default `'pin'`. */
  strategy?: 'pin' | 'cancel-events';
  /** For `cancel-events`: the scrollable region that keeps receiving input. */
  allowWithin?: React.RefObject<HTMLElement | null>;
};

const PINNED_PROPS = ['position', 'top', 'left', 'right', 'overflow'] as const;

let pinCount = 0;
let pinnedScrollY = 0;
let previousBodyStyle: Partial<Record<(typeof PINNED_PROPS)[number], string>> = {};

/**
 * Take one hold on the shared page scroll lock — the counter behind the
 * hook's `pin` strategy. For overlays outside this library (host chrome)
 * that must not fight the modal components over `document.body`. Every
 * acquire needs exactly one matching release.
 */
export function acquireScrollLock(): void {
  if (pinCount === 0) {
    const { style } = document.body;
    pinnedScrollY = window.scrollY;
    previousBodyStyle = {};
    for (const prop of PINNED_PROPS) previousBodyStyle[prop] = style[prop];
    style.position = 'fixed';
    style.top = `-${pinnedScrollY}px`;
    style.left = '0';
    style.right = '0';
    style.overflow = 'hidden';
  }
  pinCount += 1;
}

/**
 * Release one hold on the shared page scroll lock. The body styles and the
 * scroll offset are restored only when the last hold anywhere releases; an
 * unbalanced release never touches the page.
 */
export function releaseScrollLock(): void {
  if (pinCount === 0) return;
  pinCount -= 1;
  if (pinCount > 0) return;
  const { style } = document.body;
  for (const prop of PINNED_PROPS) style[prop] = previousBodyStyle[prop] ?? '';
  /* Instant, not smooth: hosts opt the html element into smooth scrolling,
     and this is a restore, not a movement the visitor should see. */
  window.scrollTo({ top: pinnedScrollY, behavior: 'instant' });
}

export function useScrollLock(active: boolean, options?: ScrollLockOptions): void {
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  const strategy = options?.strategy ?? 'pin';
  useEffect(() => {
    if (!active) return;

    if (strategy === 'pin') {
      acquireScrollLock();
      return releaseScrollLock;
    }

    const block = (event: Event) => {
      const allow = optionsRef.current?.allowWithin?.current;
      const target = event.target instanceof Node ? event.target : null;
      if (allow && target && allow.contains(target)) return;
      event.preventDefault();
    };
    document.addEventListener('wheel', block, { passive: false });
    document.addEventListener('touchmove', block, { passive: false });
    return () => {
      document.removeEventListener('wheel', block);
      document.removeEventListener('touchmove', block);
    };
  }, [active, strategy]);
}

/* ============================================
   MATERIAL SYMBOLS — Rounded only
   Variable font with FILL, GRAD, opsz, wght axes
   ============================================ */

@font-face {
  font-family: 'Material Symbols Rounded';
  font-style: normal;
  font-weight: 100 700;
  src: url('https://dragonspine-delta.vercel.app/r/assets/MaterialSymbolsRounded-VariableFont_FILL,GRAD,opsz,wght.woff2') format('woff2');
  font-display: block;
}

/* ============================================
   ICON BASE STYLES
   ============================================ */

/*
   Sizing is driven by a single custom property, `--icon-size`, which sets
   the glyph size and the layout box together so they can never desync.

   This is deliberately a *consumed* variable with a fallback, never a
   declared one: because this class only reads `--icon-size` and never sets
   it, a component that sets `--icon-size` has nothing to compete with.
   Declaring `font-size` here directly (as this file used to) tied on
   specificity with every single-class component rule and — being imported
   later — won, rendering 24px glyphs inside 20px boxes.

   Use one of the semantic steps: --icon-size-500 | -md | -lg | -xl.
*/
.material-symbols-rounded {
  font-family: 'Material Symbols Rounded';
  font-weight: normal;
  font-style: normal;
  font-size: var(--icon-size, var(--icon-size-600));
  width: var(--icon-size, var(--icon-size-600));
  height: var(--icon-size, var(--icon-size-600));
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-feature-settings: 'liga';
}

/* ============================================
   VARIABLE FONT SETTINGS
   ============================================ */

/*
   `opsz` is intentionally ABSENT from font-variation-settings. An explicit
   axis value always overrides `font-optical-sizing: auto`, so listing it
   here would silently pin every icon to one optical size regardless of how
   large it is drawn — which is exactly what this file used to do, via a
   `--material-symbols-size` hook that nothing ever set.

   With the axis omitted, the browser feeds the used font-size into `opsz`
   automatically, so stroke weight adapts to the rendered size. The font's
   axis range is 20..48; the icon-size scale starts at 20 to stay inside it.
*/
.material-symbols-rounded {
  font-optical-sizing: auto;
  font-variation-settings:
    'FILL' var(--material-symbols-fill, 0),
    'wght' var(--material-symbols-weight, 200),
    'GRAD' var(--material-symbols-grade, 0);
}

/* ============================================
   DARK THEME — optical grade correction
   Light-on-dark glyphs bloom and read heavier
   than the same strokes on a light background.
   A negative GRAD thins them back without
   changing glyph width or spacing (which is
   what `wght` would do). Material's own
   guidance for inverted surfaces.
   ============================================ */

[data-theme="dark"] {
  --material-symbols-grade: -25;
}

/* ============================================
   MODIFIER — filled variant
   ============================================ */

.icon-filled {
  --material-symbols-fill: 1;
}

/**
 * JS-driven motion timings — the TypeScript side of the motion tokens.
 * CSS transitions read the `--motion-*` custom properties; these constants
 * are the single home for timings that live in JavaScript timers, where a
 * CSS variable cannot reach. Components use them as defaults, so a single
 * instance can still be tuned through its component's own props.
 *
 * Most are schedule timings (when something starts, stops, or is taken
 * away), which the reduced-motion guard in tokens-motion.css deliberately
 * leaves alone. Constants that pace an animation (the streaming reveal's
 * rate floor and drain window, and the summary panel's reveal budget) are
 * the exception: their component checks the preference itself in JS,
 * because the CSS guard cannot see a JavaScript timer.
 */

/** Delay before a hover-triggered overlay appears, filtering pass-through hovers. */
export const MOTION_HOVER_SHOW_DELAY_MS = 300;

/** Grace period before a hover-triggered overlay or submenu closes, forgiving a wobbly pointer path. */
export const MOTION_HOVER_HIDE_DELAY_MS = 150;

/** How long a transient notification stays before dismissing itself. */
export const MOTION_AUTO_DISMISS_MS = 5000;

/** How long an exiting element's unmount waits for its CSS exit animation — mirrors --motion-duration-base. */
export const MOTION_EXIT_SYNC_MS = 200;

/** Interval between automatic slide advances. */
export const MOTION_AUTOPLAY_INTERVAL_MS = 5000;

/** How long momentary confirmation feedback (a copied state) holds before resetting. */
export const MOTION_FEEDBACK_RESET_MS = 2000;

/** How long after the last scroll event a scroll surface is considered settled. */
export const MOTION_SCROLL_SETTLE_MS = 600;

/** Slowest the streaming reveal ever runs, in characters per second — the pace a thin trickle of deltas types at. An animation pace, not a schedule timing: the reveal is skipped under reduced motion. */
export const MOTION_STREAM_FLOOR_CPS = 70;

/** However much streamed text is waiting, the reveal has it fully on screen within this long — the rate rises with the backlog, so a dumped paragraph catches up in a beat. */
export const MOTION_STREAM_DRAIN_MS = 250;

/** The retired interval-based reveal step. @deprecated The reveal is frame-driven now — pace it with MOTION_STREAM_FLOOR_CPS and MOTION_STREAM_DRAIN_MS. */
export const MOTION_STREAM_CHAR_INTERVAL_MS = 15;

/** The count-up tween's full budget: however far the number travels, AnimatedNumber has it settled within this. An animation pace, not a schedule timing: the tween is skipped under reduced motion. */
export const MOTION_COUNT_UP_MS = 800;

/** Grace period before a hover-summoned surface hides once the pointer has left it — long enough to cross the gap between a launcher and its panel without the panel dying under a mouse that is heading for it. */
export const MOTION_HOVER_EXIT_GRACE_MS = 600;

/** How long AiButton's summary panel "thinks" (skeleton lines) before its pre-written text reveals. */
export const MOTION_SUMMARY_THINK_MS = 900;

/** The summary panel's full type-out budget: however long the text, the reveal has it on screen within this. A deliberately slower pace than MOTION_STREAM_DRAIN_MS — this reveal is the content arriving, not a stream catching up. */
export const MOTION_SUMMARY_REVEAL_MS = 1600;

/** How long a suggestion row stages its "generation" (PromptSuggestions' pending shimmer) before a pre-written set reveals — the summary panel's think beat, shorter because it replays every time the set swaps rather than once per mount. A schedule timing, so the reduced-motion guard leaves it alone; the shimmer itself stills through the tokenized duration. */
export const MOTION_SUGGESTIONS_THINK_MS = 600;

