html[data-brand="contrast"] {
  --color-action-icon-active: var(--primitive-blue-02);
  --color-action-primary-bg: var(--primitive-blue-07);
  --color-action-primary-bg-active: var(--primitive-blue-09);
  --color-action-primary-bg-hover: var(--primitive-blue-08);
  --color-action-primary-border: var(--primitive-blue-10);
  --color-action-primary-border-secondary: var(--primitive-blue-07);
  --color-action-primary-border-tertiary: var(--primitive-blue-07);
  --color-action-primary-text: var(--primitive-blue-02);
  --color-action-primary-text-secondary: var(--primitive-blue-10);
  --color-action-primary-text-tertiary: var(--primitive-blue-08);
  --color-ai-gradient-end: var(--primitive-blue-07);
  --color-core-accent-amber: #E89A5E;
  --color-core-accent-cobalt: #2F5AE0;
  --color-core-accent-coral: #E86A9C;
  --color-core-accent-gold: #E8C56A;
  --color-core-accent-mint: #3FBFA8;
  --color-core-accent-violet: #7D6BE8;
  --color-core-ui-primary: var(--primitive-blue-07);
  --color-core-ui-secondary: var(--primitive-blue-10);
  --color-input-border-hover: var(--primitive-blue-06);
  --color-input-border-selected: var(--primitive-blue-07);
  --font-family-primary: 'IBM Plex Sans', sans-serif;
  --primitive-blue-00: #FAFAFD;
  --primitive-blue-01: #F3F4FB;
  --primitive-blue-02: #DCE1F2;
  --primitive-blue-03: #B8C3E6;
  --primitive-blue-04: #90A1D8;
  --primitive-blue-05: #657CC8;
  --primitive-blue-06: #405DBB;
  --primitive-blue-07: #1E40AF;
  --primitive-blue-08: #173185;
  --primitive-blue-09: #10215C;
  --primitive-blue-10: #091233;
