   PRIMITIVE TOKENS
   Source of truth — raw values only
   Do not use these directly in components
   ============================================ */

:root {
  /* ============================================
     COLOR PRIMITIVES
     ============================================ */

  /* Neutral Scale
     Alpha variants follow the -aNN grammar: NN is the alpha × 100, so
     --primitive-neutral-09-a80 is neutral-09 at 80% opacity. */
