  --primitive-neutral-01: #F1F1F1;
  --primitive-neutral-01-a01: rgba(241, 241, 241, 0.01);
  --primitive-neutral-01-a60: rgba(241, 241, 241, 0.6);
  --primitive-neutral-01-a82: rgba(241, 241, 241, 0.82);
  --primitive-neutral-02: #D6D6D6;
  --primitive-neutral-02-a80: rgba(214, 214, 214, 0.8);
  --primitive-neutral-03: #BCBCBC;
  --primitive-neutral-03-a80: rgba(188, 188, 188, 0.8);
  --primitive-neutral-04: #A2A2A2;
  --primitive-neutral-05: #888888;
  --primitive-neutral-06: #6D6D6D;
  --primitive-neutral-07: #303030;
  --primitive-neutral-07-a80: rgba(48, 48, 48, 0.8);
  --primitive-neutral-08: #232323;
  --primitive-neutral-08-a80: rgba(35, 35, 35, 0.8);
  --primitive-neutral-09: #0E0E0E;
  --primitive-neutral-09-a01: rgba(14, 14, 14, 0.01);
  --primitive-neutral-09-a80: rgba(14, 14, 14, 0.8);
  --primitive-neutral-09-a60: rgba(14, 14, 14, 0.6);
  --primitive-neutral-09-a66: rgba(14, 14, 14, 0.66);
  --primitive-neutral-10: #050505;
  --primitive-neutral-10-a60: rgba(5, 5, 5, 0.6);
  --primitive-neutral-10-a01: rgba(5, 5, 5, 0.01);
  --primitive-neutral-11: #000000;

  /* Chromatic ramps, 00–11. Step 07 is each ramp's key colour; relative
     luminance decreases strictly from 00 down to 11 (build-enforced by
     scripts/validate-theme-mirrors.mjs).

     The 00 and 11 end caps are generated, not drawn: blended gamma-aware
     in sRGB (linearize each channel, lerp linearly, delinearize) —
       00 = mix(white → step 01) at t = 0.45
       11 = mix(step 10 → black) at t = 0.38 (≈62% of step 10's luminance)
     Orange, yellow and green 05/06 are gamma-aware interpolations of
     04 → 07 at t = 1/3 and 2/3 (the hand-drawn steps sat darker than the
     07 key, kinking the ramps); every other step is the original drawn
     value. */

  /* Red Scale */
