  /* ============================================
     SPACING PRIMITIVES
     ============================================ */

  /* Spacing / Radius */
  --primitive-radius-050: 2px;
  --primitive-radius-100: 4px;
  --primitive-radius-200: 8px;
  --primitive-radius-300: 12px;
  --primitive-radius-400: 16px;
  --primitive-radius-600: 24px;
  --primitive-radius-1200: 48px;
  --primitive-radius-pill: 999px;
  /* The composer shell's corner: concentric with the 40px send button it
     wraps (half the button + the padding-sm ring + the border width).
     Held as a resolved constant so consumers re-theme it like any other

  /* Padding */
  --primitive-padding-050: 2px;
  --primitive-padding-100: 4px;
  --primitive-padding-150: 6px;
  --primitive-padding-200: 8px;
  --primitive-padding-300: 12px;
  --primitive-padding-400: 16px;
  --primitive-padding-500: 20px;
  --primitive-padding-1000: 40px;
  --primitive-padding-1500: 60px;

